export const BODY: string = "\n<p>تصویر میں پہلے سے ایک رنگ پیلیٹ ہوتا ہے جو کام کرتا ہے۔ روشنی، سطحیں، اور موضوع نے مل کر رنگ پیدا کیے جو ساتھ رہتے ہیں، اور اچھا ڈیزائنر انہیں ایجاد نہیں کرتا بلکہ نکالتا ہے۔</p>\n<p>مشکل رنگ تلاش کرنا نہیں ہے۔ مشکل یہ چننا ہے کہ کون سے استعمال کریں، ہر ایک کتنا ہو، اور کیا چھوڑ دیں، تاکہ پیلیٹ ڈیزائن کی خدمت کرے نہ کہ اس کے آگے آ جائے۔</p>\n<p>اس مضمون میں ورک فلو بتایا گیا ہے: نکالی گئی پیلیٹ سے کام کرنے والے ڈیزائن سسٹم تک، اصولوں، تناسب، اور غلطیوں کے ساتھ جو تصویر پیلیٹ کو خراب کرتی ہیں۔</p>\n<h2 id=\"why-photos-make-good-palettes\">تصاویر اچھی پیلیٹ کیوں بناتی ہیں</h2>\n<p>تصاویر رنگ ویسے ہی پکڑتی ہیں جیسے وہ اصل دنیا میں، اصل روشنی میں، اصل سطحوں پر نظر آتے ہیں۔ وہ رنگ پہلے سے ہم آہنگ ہیں، کیونکہ وہی روشنی انہیں روشن کرتی ہے۔</p>\n<p>صفر سے بنائی گئی پیلیٹ کی ایسی کوئی ضمانت نہیں۔ الگ سے چنے گئے دو رنگ ان انداز میں ٹکرا سکتے ہیں جن کا اندازہ لگانا مشکل ہے، جبکہ ایک تصویر کے دو رنگ پہلے سے ثابت کر چکے ہیں کہ وہ ساتھ رہتے ہیں۔</p>\n<p>تصاویر مزاج بھی لے کر آتی ہیں۔ گرم غروب آفتاب کی تصویر گرم پیلیٹ دیتی ہے، ٹھنڈے سمندر کی تصویر ٹھنڈی پیلیٹ دیتی ہے، اور مزاج بغیر اضافی کام کے ڈیزائن میں منتقل ہو جاتا ہے۔</p>\n<p>ایکسٹریکٹر اسے عملی بناتا ہے۔ یہ تصویر کے رنگ کوریج کے حساب سے درجہ بندی کرتا ہے، اس لیے ملنے والی پیلیٹ نہ صرف ہم آہنگ ہوتی ہے بلکہ ایمانداری سے بتاتی ہے کہ اصل میں کون سا رنگ کتنا تھا۔</p>\n<h2 id=\"dominant-vs-accent\">غالب رنگ بمقابلہ ایکسینٹ رنگ</h2>\n<p>ہر پیلیٹ کی درجہ بندی ہوتی ہے۔ غالب رنگ سب سے زیادہ جگہ گھیرتا ہے اور لہجہ طے کرتا ہے، ثانوی رنگ اس کا ساتھ دیتا ہے، اور ایکسینٹ رنگ چھوٹی مقدار میں ظاہر ہوتے ہیں۔</p>\n<p>ایکسٹریکٹر کے فیصد بیج یہ درجہ بندی سیدھا بتاتے ہیں۔ چالیس فیصد والا رنگ غالب ہے، پندرہ فیصد والا ثانوی ہے، اور تین فیصد والا ایکسینٹ ہے۔</p>\n<p>ڈیزائن میں اس درجہ بندی کا احترام کریں۔ تصویر والے تناسب میں استعمال کی گئی پیلیٹ قدرتی محسوس ہوتی ہے، کیونکہ یہ وہ توازن دہراتی ہے جسے آنکھ پہلے سے قبول کر چکی ہے۔</p>\n<p>سب سے عام غلطی ایکسینٹ کو غالب بنا دینا ہے۔ دو فیصد جگہ گھیرنے والا روشن سرخ بٹن کے طور پر شاندار لگتا ہے، مگر پس منظر کے طور پر ڈیزائن پر حاوی ہو جاتا ہے۔</p>\n<h2 id=\"the-60-30-10-rule\">60-30-10 کا اصول</h2>\n<p>60-30-10 کا اصول تصویر پیلیٹ لگانے کا سب سے آسان طریقہ ہے۔ غالب رنگ کو جگہ کا ساٹھ فیصد، ثانوی رنگ کو تیس فیصد، اور ایکسینٹ کو دس فیصد دیں۔</p>\n<p>ایکسٹریکٹر فیصد سے شروع کریں اور اصول تک گول کریں۔ پچپن، تیس، اور آٹھ فیصد والی تصویر پہلے سے مثالی کے قریب ہے، اور اصول صرف اسے پالش کرتا ہے۔</p>\n<p>اصول اس لیے کام کرتا ہے کہ یہ واضح درجہ بندی بناتا ہے۔ آنکھ جانتی ہے کہ پس منظر کیا ہے، مواد کیا ہے، اور زور کہاں ہے، بغیر اسے سمجھنے کی کوشش کیے۔</p>\n<p>اصول کو جان بوجھ کر توڑیں جب ڈیزائن مانگے، اتفاقاً نہیں۔ نوے فیصد ایکسینٹ رنگ والا پوسٹر جرات مندانہ انتخاب ہے، اور اسے انتخاب ہونا چاہیے نہ کہ حادثہ۔</p>\n<h2 id=\"warm-vs-cool-harmony\">گرم بمقابلہ ٹھنڈا ہم آہنگی</h2>\n<p>تصاویر گرم یا ٹھنڈی ہوتی ہیں، اور پیلیٹ اسی جھکاؤ کو وراثت میں لیتی ہے۔ صحرا کی تصویر گرم نارنجی اور بھورے رنگ دیتی ہے، جبکہ سردی کی تصویر ٹھنڈے نیلے اور سرمئی رنگ دیتی ہے۔</p>\n<p>گرم اور ٹھنڈے رنگ ملانے والی پیلیٹ کام کر سکتی ہے، مگر اسے واضح لیڈر چاہیے ہوتا ہے۔ ایک ٹھنڈے ایکسینٹ والی گرم پیلیٹ جان بوجھ کر لگتی ہے، جبکہ برابر تقسیم والی پیلیٹ بٹی ہوئی لگتی ہے۔</p>\n<p>ایکسٹریکٹر آؤٹ پٹ میں ہیو اقدار چیک کریں۔ صفر سے ساٹھ ڈگری کے قریب ہیو والے رنگ گرم ہوتے ہیں، ایک سو اسی سے دو سو ساٹھ ڈگری کے قریب ہیو والے ٹھنڈے ہوتے ہیں، اور ان کا توازن لہجہ طے کرتا ہے۔</p>\n<p>جب تصویر ملی ہوئی ہو تو وہ درجہ حرارت چنیں جو پیغام سے میل کھائے۔ توانائی چاہنے والا برانڈ گرم رنگ رکھتا ہے اور ٹھنڈے چھوڑ دیتا ہے، جبکہ پرسکون چاہنے والا برانڈ الٹا کرتا ہے۔</p>\n<h2 id=\"contrast-and-accessibility\">کنٹراسٹ اور رسائی</h2>\n<p>خوبصورت پیلیٹ بھی ناقابل پڑھ سکتی ہے۔ متن کو پس منظر کے خلاف کافی کنٹراسٹ چاہیے ہوتا ہے، اور تصویر پیلیٹ خود اس کی ضمانت نہیں دیتی۔</p>\n<p>پیلیٹ کے ہر متن اور پس منظر جوڑے کا کنٹراسٹ چیک کریں۔ سب سے ہلکے اور سب سے تاریک رنگ عام طور پر پاس ہوتے ہیں، جبکہ ایک ہی تصویر کے دو درمیانی رنگ اکثر ناکام ہوتے ہیں۔</p>\n<p>HSL اس میں مدد کرتا ہے۔ جن دو رنگوں کی ہلکی پن اقدار بہت دور ہوں وہ عام طور پر کنٹراسٹ چیک پاس کرتے ہیں، جبکہ جن کی ہلکی پن اقدار ایک جیسی ہوں وہ ناکام ہوتے ہیں، چاہے ان کا ہیو کچھ بھی ہو۔</p>\n<p>جب جوڑا ناکام ہو تو ہلکی پن ایڈجسٹ کریں، ہیو نہیں۔ متن رنگ کو دس پوائنٹ تاریک کریں یا پس منظر کو دس پوائنٹ ہلکا کریں، اور پیلیٹ اپنی شخصیت رکھتی ہے جبکہ پڑھنے کے قابل ہو جاتی ہے۔</p>\n<h2 id=\"from-palette-to-design-system\">پیلیٹ سے ڈیزائن سسٹم تک</h2>\n<p>پیلیٹ تب ڈیزائن سسٹم بنتی ہے جب ہر رنگ کو کردار ملے۔ سوئچ کو ان کے کام سے نام دیں، جیسے پس منظر، سطح، بنیادی، ثانوی، ایکسینٹ، اور متن۔</p>\n<p>کردار پیلیٹ کو ٹیم کے لیے قابل استعمال بناتے ہیں۔ ایک ڈویلپر جو accent نامی ویری ایبل دیکھتا ہے جانتا ہے کہ اسے کہاں استعمال کرنا ہے، جبکہ orange-3 نامی ویری ایبل اندازے کی دعوت دیتا ہے۔</p>\n<p>بنیادی رنگوں سے HSL میں صرف ہلکی پن بدل کر شیڈ بنائیں۔ پچاس فیصد ہلکی پن والا بنیادی رنگ بیالیس فیصد پر ہوور حالت اور ساٹھ فیصد پر نرم سطح پیدا کر سکتا ہے۔</p>\n<p>سسٹم کو ڈیزائن ٹوکن کے طور پر محفوظ کریں، اور انہیں ایکسٹریکٹر JSON سے ایکسپورٹ کریں۔ JSON بنیادی رنگ دیتا ہے، اور ٹوکن کردار اور مختلف حالتوں کو دستاویز کرتے ہیں۔</p>\n<h2 id=\"mood-boards\">تصاویر سے موڈ بورڈ</h2>\n<p>موڈ بورڈ تصاویر کا مجموعہ ہے جو ایک احساس شیئر کرتی ہیں، اور ان کی پیلیٹ کو ایک دوسرے سے متفق ہونا چاہیے۔ ہر تصویر سے پیلیٹ نکالیں اور ان کا موازنہ کریں۔</p>\n<p>جب پیلیٹ غالب ہیو یا ایک جیسا درجہ حرارت شیئر کریں تو بورڈ مربوط محسوس ہوتا ہے۔ جب وہ مختلف سمتوں میں کھینچیں تو بورڈ بکھرا محسوس ہوتا ہے، چاہے تصاویر الگ الگ اچھی ہوں۔</p>\n<p>ایکسٹریکٹر کے پیلیٹ کارڈز کو خود بورڈ کے طور پر استعمال کریں۔ ہر کارڈ تصویر کو اس کے سوئچ کے ساتھ دکھاتا ہے، اس لیے بورڈ تصاویر اور ان کے رنگ دونوں بتاتا ہے۔</p>\n<p>اس طرح بنایا گیا موڈ بورڈ فیصلے کا ریکارڈ بھی ہوتا ہے۔ جب کلائنٹ پوچھے کہ یہ رنگ کیوں، تو بورڈ وہ تصاویر دکھاتا ہے جن سے وہ آئے، جو کسی بھی وضاحت سے مضبوط جواب ہے۔</p>\n<h2 id=\"brand-palettes-from-photos\">تصاویر سے برانڈ پیلیٹ</h2>\n<p>برانڈ اکثر تصویر سے شروع ہوتے ہیں: بانی کی تصویر، پروڈکٹ شاٹ، یا کمپنی کے لیے اہم جگہ۔ اس تصویر سے نکالی گئی پیلیٹ کمپنی کی کہانی لے کر آتی ہے۔</p>\n<p>برانڈ کام کے لیے ماخذ تصویر کے بہترین ورژن سے نکالیں، پھر پیلیٹ کو چار یا پانچ رنگوں تک کم کریں۔ برانڈ پیلیٹ کو یادگار ہونا چاہیے، اور دس رنگوں والی پیلیٹ کوئی یاد نہیں رکھتا۔</p>\n<p>نکالنے کے بعد کلیدی رنگ امیج کلر پکر سے تصدیق کریں۔ پکر درست پکسل پڑھتا ہے، جو برانڈ رنگ کی تصدیق کرتا ہے جب ایکسٹریکٹر قدر قریب ہو مگر یقین نہ ہو۔</p>\n<p>پیلیٹ کو ماخذ تصویر، اس کی HEX، RGB، اور CMYK اقدار، اور اس کے کرداروں کے ساتھ دستاویز کریں۔ رنگوں کے ساتھ تصویر دکھانے والا برانڈ گائیڈ کہانی سناتا ہے، صرف نمبر نہیں۔</p>\n<h2 id=\"seasonal-and-cultural-cues\">موسمی اور ثقافتی اشارے</h2>\n<p>رنگ ایسی وابستگیاں لے کر آتے ہیں جو موسم اور ثقافت کے ساتھ بدلتی ہیں۔ خزاں کی تصویر نارنجی اور بھورے رنگ دیتی ہے جو اکتوبر میں درست اور مئی میں بھاری لگتے ہیں، جبکہ بہار کی تصویر ہلکے سبز رنگ دیتی ہے۔</p>\n<p>جب آپ تصویر کو پیلیٹ ماخذ کے طور پر چنیں تو سوچیں کہ ڈیزائن کب اور کہاں دیکھا جائے گا۔ مہم کی پیلیٹ کو اپنے موسم سے ملنا چاہیے، اور عالمی برانڈ پیلیٹ کو کسی ایک ثقافت کی وابستگی سے بچنا چاہیے۔</p>\n<p>ایکسٹریکٹر ان وابستگیوں کا فیصلہ نہیں کر سکتا؛ یہ صرف رنگ رپورٹ کرتا ہے۔ فیصلہ ڈیزائنر کا ہوتا ہے، جو سامعین اور لمحے کو جانتا ہے۔</p>\n<p>جب شک ہو تو پیلیٹ کو سامعین کے لوگوں کے ساتھ ٹیسٹ کریں۔ پانچ منٹ کی گفتگو ایسی وابستگی ظاہر کر سکتی ہے جو گھنٹوں کا ڈیزائن کام چھوٹ جائے۔</p>\n<h2 id=\"avoiding-muddy-palettes\">کیچڑ والی پیلیٹ سے بچنا</h2>\n<p>تصویر پیلیٹ تب کیچڑ والی ہو جاتی ہے جب بہت سے درمیانی رنگ مقابلہ کریں۔ پانچ ایک جیسے بھورے اور سرمئی رنگ والی تصویر ایسی پیلیٹ دیتی ہے جہاں کچھ نمایاں نہیں ہوتا اور سب کچھ ایک جیسا لگتا ہے۔</p>\n<p>حل گھٹانا ہے۔ ایک دوسرے کے قریب درمیانی رنگ چھوڑ دیں، سب سے ہلکا اور سب سے تاریک رکھیں، اور ایک واضح ایکسینٹ رکھیں۔ کنٹراسٹ والی پیلیٹ صاف پڑھتی ہے۔</p>\n<p>کیچڑ کی دوسری وجہ مختلف روشنی والی تصاویر ملانا ہے۔ گرم تصویر اور ٹھنڈی تصویر الگ الگ اچھی پیلیٹ دیتی ہیں، مگر انہیں ملانے سے ایسی پیلیٹ بنتی ہے جس کا کوئی لہجہ نہیں۔</p>\n<p>جب پیلیٹ کیچڑ والی محسوس ہو تو HSL اقدار چیک کریں۔ اگر سب کی سیچوریشن اقدار کم اور ہلکی پن اقدار درمیان میں ہوں تو پیلیٹ کو روشن رنگ اور تاریک لنگر چاہیے ہوتا ہے۔</p>\n<h2 id=\"testing-a-palette\">عہد کرنے سے پہلے پیلیٹ ٹیسٹ کرنا</h2>\n<p>عہد کرنے سے پہلے اصل لے آؤٹ میں پیلیٹ ٹیسٹ کریں۔ سوئچ کے طور پر اچھی لگنے والی پیلیٹ صفحے کے طور پر ناکام ہو سکتی ہے، کیونکہ سوئچ کنٹراسٹ، درجہ بندی، یا پڑھنے کی اہلیت نہیں دکھاتے۔</p>\n<p>پیلیٹ لگا کر فوری موک بنائیں: سرخی، پیراگراف، بٹن، اور کارڈ۔ اگر موک اچھا پڑھے تو پیلیٹ کام کرتی ہے۔ اگر عجیب محسوس ہو تو موک بتاتا ہے کہ کہاں۔</p>\n<p>گرے اسکیل میں بھی ٹیسٹ کریں۔ موک کو سیاہ اور سفید میں بدلیں اور چیک کریں کہ درجہ بندی بچتی ہے یا نہیں۔ صرف ہیو پر منحصر پیلیٹ گر جاتی ہے، جبکہ ہلکی پن پر بنی پیلیٹ بچتی ہے۔</p>\n<p>فون اسکرین پر بھی ٹیسٹ کریں۔ رنگ چھوٹی روشن اسکرین پر مختلف لگتے ہیں، اور بڑے مانیٹر پر کام کرنے والی پیلیٹ فون پر سخت یا دھلی ہوئی محسوس ہو سکتی ہے۔</p>\n<h2 id=\"palette-and-typography\">پیلیٹ اور ٹائپوگرافی ساتھ</h2>\n<p>رنگ اور ٹائپ جوڑے کے طور پر کام کرتے ہیں، اور پیلیٹ انتخاب ٹائپوگرافی کو محدود کرتا ہے۔ مصروف، رنگین پیلیٹ کو پرسکون، سادہ ٹائپ چاہیے ہوتی ہے، جبکہ تحمل والی پیلیٹ زیادہ اظہار والی ٹائپ برداشت کر سکتی ہے۔</p>\n<p>متن رنگ پیلیٹ جتنی ہی توجہ کا حقدار ہے۔ پیلیٹ کا سب سے تاریک رنگ عام طور پر متن رنگ ہوتا ہے، اور اسے آرام سے پڑھنے کے لیے کافی تاریک ہونا چاہیے۔</p>\n<p>لنک اور انٹرایکٹو عناصر کو ایسا رنگ چاہیے ہوتا ہے جو متن سے الگ کھڑا ہو۔ ایکسینٹ رنگ عام طور پر یہ کردار بھرتا ہے، اور اسے اتنا الگ ہونا چاہیے کہ دیکھنے والا اسے کلک کرنے والا پہچانے۔</p>\n<p>جب پیلیٹ تصویر سے آئے تو تصویر خود ٹائپ رنگ دے سکتی ہے۔ پکر سے تصویر کے سب سے تاریک سائے کا نمونہ لیں، اور وہ لہجہ پیلیٹ سے ہم آہنگ ہو گا۔</p>\n<h2 id=\"iterating-on-a-palette\">پیلیٹ پر تکرار</h2>\n<p>پیلیٹ پہلی نکال پر شاذ و نادر ہی درست ہوتی ہے۔ پہلی پیلیٹ کو مسودہ سمجھیں، اسے موک میں استعمال کریں، دیکھیں کہ کیا ناکام ہوتا ہے، اور مختلف تصویر یا تعداد سے دوبارہ نکالیں۔</p>\n<p>ورژن رکھیں۔ ویب سائٹ کے لیے غلط پیلیٹ پوسٹر کے لیے درست ہو سکتی ہے، اور چھوڑا ہوا ورژن بعد کے بریف کا جواب بن سکتا ہے۔</p>\n<p>چھوٹے قدموں میں تکرار کریں۔ ایک وقت میں ایک رنگ بدلیں، یا تعداد ایک سے بدلیں، تاکہ آپ بتا سکیں کہ کس تبدیلی نے نتیجہ بہتر کیا اور کس نے خراب کیا۔</p>\n<p>تب رک جائیں جب پیلیٹ اپنا کام کرے۔ اچھی اور استعمال میں پیلیٹ کامل اور ابھی زیر بحث پیلیٹ سے بہتر ہوتی ہے، اور ایکسٹریکٹر دوبارہ نکالنا آسان بناتا ہے۔</p>\n<h2 id=\"palettes-for-data-visualization\">ڈیٹا ویژولائزیشن کے لیے پیلیٹ</h2>\n<p>چارٹ اور گراف کو لے آؤٹ سے مختلف منطق والی پیلیٹ چاہیے ہوتی ہے۔ ہر ڈیٹا سیریز کو ایسا رنگ چاہیے ہوتا ہے جو ایک نظر میں دوسروں سے الگ ہو، اور پیلیٹ کو یہ فرق ہر سائز پر رکھنا چاہیے۔</p>\n<p>تصویر سے نکالی گئی پیلیٹ کو چارٹ کے لیے صرف رنگوں کو ایک دوسرے کے خلاف چیک کرنے کے بعد استعمال کریں۔ سوئچ کے طور پر مختلف لگنے والے دو رنگ چارٹ میں ایک جیسے لگ سکتے ہیں۔</p>\n<p>زمرہ جاتی ڈیٹا کے لیے بڑے پیمانے پر الگ ہیو والے رنگ چنیں۔ صفر، ایک سو بیس، اور دو سو چالیس ڈگری کے فاصلے والے ہیو سے بنی پیلیٹ سیریز کو الگ کرنا آسان بناتی ہے۔</p>\n<p>ترتیبی ڈیٹا کے لیے ایک ہی ہیو کو مختلف ہلکی پن کے ساتھ استعمال کریں۔ ہلکے نیلے سے تاریک نیلے تک کا پیمانہ ترقی کے طور پر پڑھتا ہے، جبکہ ہیو کا قوس رنگ ترقی کے طور پر نہیں پڑھتا۔</p>\n<p>چارٹ پیلیٹ کو گرے اسکیل اور رنگ اندھا پن سمیلیٹر سے ٹیسٹ کریں۔ دونوں ٹیسٹ سے بچنے والی پیلیٹ تقریباً ہر قاری کے لیے کام کرتی ہے، جو معیار ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: تصویر پیلیٹ ورک فلو</h2>\n<p>اپنی پسندیدہ تصویر سے نکالیں، فیصد پڑھیں، 60-30-10 کا اصول لگائیں، متن کے لیے کنٹراسٹ چیک کریں، اور کچھ بھی بنانے سے پہلے ہر رنگ کو کردار دیں۔</p>\n<p>نقل کم کریں، چھوٹے ایکسینٹ کو آئی ڈراپر سے بچائیں، اور عہد کرنے سے پہلے پیلیٹ کو اصل لے آؤٹ، گرے اسکیل، اور فون پر ٹیسٹ کریں۔</p>\n<p>تصویر پیلیٹ اس لیے کام کرتی ہے کہ رنگ پہلے سے ثابت کر چکے ہیں کہ وہ ساتھ رہتے ہیں۔ آپ کا کام انہیں چننا، تناسب دینا، اور نام دینا ہے، صفر سے ایجاد کرنا نہیں۔</p>\n<p>پیلیٹ نکالنے کے لیے <a href=\"/ur/tasveer-se-rang-palette-nikalein/\">image color palette extractor</a> استعمال کریں، اور درست واحد پکسل کے لیے <a href=\"/ur/tasveer-se-rang-chunein/\">image color picker</a> استعمال کریں۔ مکمل پس منظر کے لیے <a href=\"/ur/blog/tasveer-rang-palette-extractor-rehnumai/\">Colour Palette Extractor: Complete Guide</a> پڑھیں۔</p>\n";

